window.ScripturaLexicons.BDAG_PART_0180 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-01\" data-source=\"BDAG\" data-search=\"Ἰωσήχ, ὁ nome próprio masculino Joseque; filho de Jodá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰωσήχ, ὁ</td><td>nome próprio masculino</td><td>Joseque; filho de Jodá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-02\" data-source=\"BDAG\" data-search=\"Ἰωσίας, ου, ὁ nome próprio masculino Josias; rei de Judá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰωσίας, ου, ὁ</td><td>nome próprio masculino</td><td>Josias; rei de Judá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-03\" data-source=\"BDAG\" data-search=\"ἰῶτα, τό substantivo neutro; indeclinável iota; menor letra; numeral dez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰῶτα, τό</td><td>substantivo neutro; indeclinável</td><td>iota; menor letra; numeral dez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-04\" data-source=\"BDAG\" data-search=\"κ´ sinal numérico numeral vinte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κ´</td><td>sinal numérico</td><td>numeral vinte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-05\" data-source=\"BDAG\" data-search=\"κάβος, ου, ὁ substantivo masculino cabo; medida de cerca de dois litros BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάβος, ου, ὁ</td><td>substantivo masculino</td><td>cabo; medida de cerca de dois litros</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-06\" data-source=\"BDAG\" data-search=\"κἀγώ pronome pessoal em crase e eu; mas eu; eu também; se eu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀγώ</td><td>pronome pessoal em crase</td><td>e eu; mas eu; eu também; se eu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-07\" data-source=\"BDAG\" data-search=\"κάδος, ου, ὁ substantivo masculino jarro; recipiente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάδος, ου, ὁ</td><td>substantivo masculino</td><td>jarro; recipiente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-08\" data-source=\"BDAG\" data-search=\"καθά conjunção; advérbio assim como; da maneira pela qual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθά</td><td>conjunção; advérbio</td><td>assim como; da maneira pela qual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-09\" data-source=\"BDAG\" data-search=\"καθαίρεσις, εως, ἡ substantivo feminino demolição; destruição; incapacitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαίρεσις, εως, ἡ</td><td>substantivo feminino</td><td>demolição; destruição; incapacitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-10\" data-source=\"BDAG\" data-search=\"καθαιρέτης, ου, ὁ substantivo masculino destruidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαιρέτης, ου, ὁ</td><td>substantivo masculino</td><td>destruidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-11\" data-source=\"BDAG\" data-search=\"καθαιρέω verbo tirar, derrubar; destruir, subjugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαιρέω</td><td>verbo</td><td>tirar, derrubar; destruir, subjugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-12\" data-source=\"BDAG\" data-search=\"καθαίρω verbo limpar, purificar; podar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαίρω</td><td>verbo</td><td>limpar, purificar; podar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-13\" data-source=\"BDAG\" data-search=\"καθάπερ conjunção; advérbio assim como; tal como BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθάπερ</td><td>conjunção; advérbio</td><td>assim como; tal como</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-14\" data-source=\"BDAG\" data-search=\"καθάπτω verbo agarrar, apoderar-se de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθάπτω</td><td>verbo</td><td>agarrar, apoderar-se de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-15\" data-source=\"BDAG\" data-search=\"καθαρεύω verbo estar limpo; estar livre de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρεύω</td><td>verbo</td><td>estar limpo; estar livre de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-16\" data-source=\"BDAG\" data-search=\"καθαρίζω verbo limpar; curar; purificar; declarar limpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρίζω</td><td>verbo</td><td>limpar; curar; purificar; declarar limpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-17\" data-source=\"BDAG\" data-search=\"καθαρισμός, οῦ, ὁ substantivo masculino purificação; limpeza cultual ou moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>purificação; limpeza cultual ou moral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-18\" data-source=\"BDAG\" data-search=\"κάθαρμα, ατος, τό substantivo neutro refugo; escória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάθαρμα, ατος, τό</td><td>substantivo neutro</td><td>refugo; escória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-19\" data-source=\"BDAG\" data-search=\"καθαρός, ά, όν adjetivo limpo; ritualmente puro; livre de culpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρός, ά, όν</td><td>adjetivo</td><td>limpo; ritualmente puro; livre de culpa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0180-20\" data-source=\"BDAG\" data-search=\"καθαρότης, ητος, ἡ substantivo feminino pureza; estado de purificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρότης, ητος, ἡ</td><td>substantivo feminino</td><td>pureza; estado de purificação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0180-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰωσήχ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( Mlt-H. 108f) Joseque, filho de Jodá, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:26</a> ( variante de leitura <span class=\"greek\">Ἰωσήφ</span> , ver o verbete, acepção 10).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰωσίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(também com a terminação -<span class=\"greek\">είας</span> ; יאֹשִׁיָּהוּ ) Josias, rei de Judá ( 4 Km 22f ; 2 Ch 34f ; Sir 49:1, 4 ; Bar 1:8 ; 1 Esdr 1:1–32 ; Jos. , Ant. 10:48, 67–77); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:10f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23ff</a> D (aqui, o genitivo <span class=\"greek\">Ἰωσία</span> ).— EDNT .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰῶτα, τό</h1><div class=\"entry-meta\"><span>substantivo neutro; indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável (escrito por extenso como palavra Plato, Cratyl. 418b; Aeneas Tact . 1506; escoliasta de Nicander , Ther. 950; Sb 358, 12; 20 [III b.c. ]) iota. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a> é evidentemente o equivalente grego do yod aramaico, o qual, na forma original do dito, representava a menor letra do alfabeto (ver MLidzbarski, Handb. d. nord semit. Epigraphik 1898, 190ff; ESutcliffe, Biblica 9, 1928, 458–62). Como numeral = dez B 9:8 . Ver <span class=\"greek\">ι</span>´ como numeral.— DELG . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κ´</h1><div class=\"entry-meta\"><span>sinal numérico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">sinal numérico = 20 ( <span class=\"greek\">εἴκοσι</span> : a tradição textual varia entre <span class=\"greek\">κ</span>´ e <span class=\"greek\">κε</span>´ [=25]) Hs 9, 4, 3 ; 9, 5, 4 .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάβος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(empréstimo vocabular semítico [ קַב ; ver Masson 84] Geopon . 7, 20, 1; 4 Km 6:25 ) medida (habitualmente de grãos etc.) equivalente a aproximadamente dois litros, cabo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:6</a> variante de leitura ; ver <span class=\"greek\">κάδος</span> .— DELG .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀγώ</h1><div class=\"entry-meta\"><span>pronome pessoal em crase</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(atestado desde Il. 21, 108, também em inscrições [Meisterhans 3 -Schw. 72]; papiros [ Mayser 159 com exemplos de todos os casos; ver também UPZ 78, 15 [159 b.c. ]; PSI 540, 17; PTebt 412, 4 <span class=\"greek\">καἰγώ</span> ]; LXX [ Thackeray 137f]; literatura pseudepígrafa ; Jos. , Ant. 7, 212 ; Just .; Tat . 5:2. Formado por crase de <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐγώ</span>, como se encontra na maioria das edições ) dativo <span class=\"greek\">κἀμοί</span>, acusativo <span class=\"greek\">κἀμέ</span> . Ver B-D-F § 18 ; W-S. §5, 9; Mlt-H. 84.</p><p class=\"entry-text\">① e eu <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">σου</span> <span class=\"greek\">κἀγώ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:48</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:57</a> ; 7:28 ; 8:26 ; 10:28 ; 17:22 ; IPhld 11:1 al. —Numa narrativa contada na primeira pessoa do singular, vincula um elemento a outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:31</a>, 33, 34. Frequentemente exprime uma relação recíproca: «e eu», «assim como eu» <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">μένει</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:56</a>. <span class=\"greek\">μείνατε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> 15:4 ; cf. 10:15, 38 ; 14:20 ; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:20</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:14</a>.</p><p class=\"entry-text\">② mas eu: Jesus em contraste com o príncipe deste mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:32</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:19</a>. <span class=\"greek\">ὑμεῖς</span> … <span class=\"greek\">κἀμοί</span> vós … mas a mim 10:28. <span class=\"greek\">σὺ</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχεις</span>, <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">ἔχω</span> tu tens fé, mas eu tenho obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:18a</a>.</p><p class=\"entry-text\">③ eu também, igualmente eu</p><p class=\"entry-text\">ⓐ = eu, assim como outros <span class=\"greek\">δοκῶ</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔχειν</span> creio que também eu tenho o Espírito de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:40</a>. <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">προσκυνήσω</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:3</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:19</a>. — «eu também» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:21</a>, 22abc. — <span class=\"greek\">καθὼς</span> … <span class=\"greek\">κἀγώ</span> assim como … também eu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:9</a> ; 17:18 ; 20:21.</p><p class=\"entry-text\">ⓑ eu, de minha parte; eu, por minha vez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:32f</a> ; 26:15 (ver acepção 5 abaixo); 18:33 ; 21:24 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:29</a> ; B 1:4 ; ISm 4:2 . <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐτήρησας</span> … <span class=\"greek\">κἀγώ</span> <span class=\"greek\">σε</span> <span class=\"greek\">τηρήσω</span> porque guardaste … também eu, por minha vez, te guardarei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>. —Introduzindo a lição moral de uma parábola <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">λέγω</span> eu, de minha parte, vos digo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:9</a> (cf. 16:9 ).— <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">δέ</span> mas eu, de minha parte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:18</a>.</p><p class=\"entry-text\">ⓒ O <span class=\"greek\">καί</span> de <span class=\"greek\">κἀγώ</span> é redundante na comparação <span class=\"greek\">τοιούτους</span> <span class=\"greek\">ὁποῖος</span> <span class=\"greek\">κἀγώ</span> <span class=\"greek\">εἰμι</span> tal como eu sou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>, variante de leitura <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μείνωσιν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κἀγώ</span> se permanecerem como eu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:8</a> ; cf. 10:33 ; 11:1. De modo semelhante, <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">παύομαι</span> por essa razão não cesso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:15</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>.</p><p class=\"entry-text\">④ eu em particular, ou eu, por exemplo <span class=\"greek\">τί</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἁμαρτωλὸς</span> <span class=\"greek\">κρίνομαι</span> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:7</a>.</p><p class=\"entry-text\">⑤ se eu; introduz, na realidade, uma oração condicional <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">παραδώσω</span> <span class=\"greek\">αὐτόν</span> se eu vo-lo entregar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:15</a> (cf. SIG 1168, 69f <span class=\"greek\">τί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">δωσεῖς</span>, <span class=\"greek\">αἴ</span> <span class=\"greek\">τύ</span> <span class=\"greek\">κα</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">ποιήσω</span>; Que me darás se eu te curar? Sobre a interpretação de <span class=\"greek\">κἀγώ</span> como introdução de uma prótase, ver Rob. 951 .)— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάδος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(palavra semítica, ver Masson 42–44; desde Arquíloco Lyr ., Anacr ., Hdt. ; GDI 5220 [Sicília: 18 ocorrências]; papiros ; Is 40:15 ; 2 Ch 2:9 variante de leitura, <span class=\"greek\">ἐλαίου</span> <span class=\"greek\">κάδ</span> .) jarro, recipiente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:6</a> variante de leitura (em lugar de <span class=\"greek\">βάτος</span> II); ver <span class=\"greek\">κάβος</span> .— DELG .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθά</h1><div class=\"entry-meta\"><span>conjunção; advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">conjunção ou advérbio (since Polyb . 3, 107, 10 [FKälker, Quaest. de elocut. Polyb . 1880, 300]; Diod S 4, 81, 3; 19, 48, 2; 19, 71, 7; inscrições [Meisterhans 3 -Schw. 257; índice de SIG]; PRyl 160 II, 18; POxy 1473, 10; LXX ; PsSol 2:12 ; TestAbr B 5 p. 109, 19 [Stone p. 66]; TestJob 17:4; JosAs 24:10f; ParJer 3:22 [AB]; Jos. , Ant. 19, 96 ; 298 ; 20, 6 ; Ar. 4, 2; Just .; Tat . 1, 2; Ath. 20, 2) assim como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a> D (ver B-D-F § 453 ); IMg 10:1 ; Hs 1:8 ; AcPl Ha 5, 18.— como, da maneira pela qual <span class=\"greek\">ἄκουε</span> … , <span class=\"greek\">καθὰ</span> <span class=\"greek\">δῖ</span> (= <span class=\"greek\">δεῖ</span> ) <span class=\"greek\">σε</span> <span class=\"greek\">σωθῆναι</span> AcPl Ha 1, 5; Hs 8, 7, 1 variante de leitura — M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαίρεσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθαιρέω</span> ; Tucídides e outros ; inscrições e papiros , LXX ; Jos. , Ant. 14, 437 ) em geral, «demolição, destruição».</p><p class=\"entry-text\">① causar destruição por demolição; derrubada, demolição, destruição, literalmente ( <span class=\"greek\">τ</span>. <span class=\"greek\">τειχῶν</span> X. , Hell. 2, 2, 15; 5, 1, 35; Polyb . 23, 7, 6 variante de leitura ; SIG 2 587, 76; PMagd 96 [III b.c. ] demolição de um templo; Ex 23:24 <span class=\"greek\">καθαιρέσει</span> <span class=\"greek\">καθελεῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στήλας</span> <span class=\"greek\">αὐτῶν</span> ; Jos. , Ant. 17, 163 ) no discurso ilustrativo ( cf. Philo , Conf. Lingu. 130 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀχυρώματος</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">καθαίρεσιν</span> ) <span class=\"greek\">πρὸς</span> <span class=\"greek\">καθαίρεσιν</span> <span class=\"greek\">ὀχυρωμάτων</span> para a demolição de fortificações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a>.</p><p class=\"entry-text\">② causar enfraquecimento da capacidade; incapacitação, extensão figurada da acepção 1 ( Diod S 34 + 35, Fgm. 7, 1 referindo-se à destituição de um cargo; Philo ; em oposição a <span class=\"greek\">οἰκοδομή</span> [ ver verbete ]=«edificação») <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">καθαίρεσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:10</a>. Com genitivo objetivo de pessoa <span class=\"greek\">εἰς</span> <span class=\"greek\">καθαίρεσιν</span> <span class=\"greek\">ὑμῶν</span> 10:8 ( cf. 1 Macc 3:43 <span class=\"greek\">καθ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> ).— DELG sob o verbete <span class=\"greek\">αἱρέω</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαιρέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθαιρέω</span> ; since Thu . 4, 83, 5; BGU 14 V, 12 [255 a.d. ]) destruidor <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμετέρων</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">κ</span> . MPol 12:2 .— DELG sob o verbete <span class=\"greek\">αἱρέω</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαιρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">2º futuro <span class=\"greek\">καθελῶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:18</a> ; 1º aoristo, imperativo, 2ª pessoa plural <span class=\"greek\">καθαιρήσατε</span> ( Just ., A I, 56, 4); 2º aoristo <span class=\"greek\">καθεῖλον</span> , particípio <span class=\"greek\">καθελών</span> . Passivo: futuro <span class=\"greek\">καθαιρεθήσομαι</span> LXX ; 1º aoristo <span class=\"greek\">καθῃρέθην</span> ; particípio perfeito <span class=\"greek\">καθῃρημένος</span> LXX ; mais-que-perfeito, 3ª pessoa singular <span class=\"greek\">καθῄρητο</span> Judg 6:28 B ( Homero e posteriores).</p><p class=\"entry-text\">① fazer descer de um nível para outro; tirar, descer, baixar ( Demetr . [?]: 722 Fgm. 7 Jac. ) <span class=\"greek\">τινά</span> ou <span class=\"greek\">τὶ</span> alguém ou alguma coisa : alguém de um veículo MPol 8:3 . Judas de uma árvore Papias (3:1). Referindo-se a mãos erguidas: deixá-las baixar B 12:2 (com <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> subentendido); o corpo da cruz ( Polyb . 1, 86, 6; Philo , In Flacc. 83 ; Jos. , Bell. 4, 317 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>, 46 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξύλου</span> ( Josh 8:29 ; 10:27 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:29</a>. <span class=\"greek\">δυνάστας</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θρόνων</span> derrubar os governantes de seus tronos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:52</a> ( <span class=\"greek\">κ</span> . em emprego absoluto nesse sentido : Hdt. 7, 8, 1; Aelian , VH 2, 25; Jos. , Ant. 8, 270 ; sobre o tema, cf. 3 Macc 2:2–20 ).</p><p class=\"entry-text\">② destruir mediante derrubada; demolir, destruir, subjugar</p><p class=\"entry-text\">ⓐ literalmente <span class=\"greek\">α</span>. referindo-se a edifícios: demolir ( X. , Hell. 4, 4, 13 <span class=\"greek\">τῶν</span> <span class=\"greek\">τειχῶν</span> =uma parte dos muros; SIG 826e, 31 <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκίαν</span> ; PAmh 54, 3; Is 5:5 ; 22:10 ; Jos. , Vi. 65 ; Just ., A I, 56, 4 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀνδριάντα</span> ) em contraste com <span class=\"greek\">οἰκοδομέω</span> ( Jer 49:10 ; 51:34 ; Ezk 36:36 ): o templo B 16:3 ( cf. Diod S 20, 93, 1 <span class=\"greek\">ἱερά</span> ; Is 49:17 ). Celeiros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:18</a>. Voz passiva em B 16:4 . <span class=\"greek\">β</span>. conquistar, destruir ( Thu . 1, 4; 1, 77, 6 al. ; Aelian , VH 2, 25; POxy 1408, 23 <span class=\"greek\">τοὺς</span> <span class=\"greek\">λῃστάς</span> ; EpArist 263 ; Philo , Agr . 86; Jos. , Ant. 10, 209 ; <span class=\"greek\">δαίμονας</span> <span class=\"greek\">κ</span> . Orig ., C. Cels. 8, 73, 29) <span class=\"greek\">ἔθνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:19</a>. Voz passiva: <span class=\"greek\">καθαιροῦνται</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> IEph 13:1 .</p><p class=\"entry-text\">ⓑ figuradamente ( Epict . 1, 28, 25 <span class=\"greek\">τὰ</span> <span class=\"greek\">δόγματα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀρθὰ</span> <span class=\"greek\">κ</span> .; Zech 9:6 <span class=\"greek\">καθελῶ</span> <span class=\"greek\">ὕβριν</span> <span class=\"greek\">ἀλλοφύλων</span> ; Jos. , Ant. 6, 179 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀλαζονείαν</span> ; Tat . 26, 3 <span class=\"greek\">πολεμούντες</span> … <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">καθαιρεῖτε</span> ; Iren. 1, 15, 2 [ Harv. I 149, 8] <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> ) <span class=\"greek\">λογισμούς</span> destruir sofismas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a>. Voz passiva: <span class=\"greek\">ἄγνοια</span> IEph 19:3 . <span class=\"greek\">καθαιρεῖσθαι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγαλειότητος</span> <span class=\"greek\">αὐτῆς</span> sofrer a perda de sua magnificência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a> ( cf. Achmes 13, 22 <span class=\"greek\">ὁ</span> <span class=\"greek\">κριτὴς</span> … <span class=\"greek\">καθαιρεῖται</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀξίας</span> <span class=\"greek\">αὐτοῦ</span> =o juiz sofre a perda de sua dignidade; B-D-F § 180, 1 ; Rob. 518 . Field, Notes 129f propõe acrescentar <span class=\"greek\">τὶ</span> e traduzir «diminuir» ).— DELG sob o verbete <span class=\"greek\">αἱρέω</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαίρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">particípio do 1º aoristo <span class=\"greek\">καθάρας</span> ; particípio médio do aoristo <span class=\"greek\">καθηράμενος</span> ( Just ., D . 4, 3); perfeito passivo, 3ª pessoa do singular <span class=\"greek\">κεκάθαρται</span> Hs 9, 10, 4 ; particípio <span class=\"greek\">κεκαθαρμένος</span> ( Homero e posteriores)</p><p class=\"entry-text\">① tornar algo limpo; limpar, literalmente, referindo-se a um lugar varrido ( cf. Diod S 19, 13, 4 <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀνακαθαίρειν</span> =limpar [desobstruir] um lugar): <span class=\"greek\">πάντα</span> <span class=\"greek\">κεκάθαρται</span> tudo está limpo Hs 9, 10, 4 . Figuradamente ( Diod S 4, 31, 4; 4, 69, 4; Dio Chrys . 60 + 61 [77 + 78], 40 <span class=\"greek\">τὴν</span> <span class=\"greek\">αὑτοῦ</span> <span class=\"greek\">διάνοιαν</span> <span class=\"greek\">καθαίρει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> ; Himerius , Or. 41 [=Or. 7], 1 <span class=\"greek\">Ἡλίῳ</span> <span class=\"greek\">Μίθρᾳ</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">καθάραντες</span> =após purificarmos nossa alma por intermédio de Hélio Mitra; Philo , Somn. 1, 198 <span class=\"greek\">καθαίρει</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ἁμαρτημάτων</span> ; Jos. , Ant. 5, 42 ; Just ., D . 4, 3 al. ) <span class=\"greek\">οἱ</span> <span class=\"greek\">κεκαθαρμένοι</span> os que foram purificados Hs 9, 18, 3 . <span class=\"greek\">καθᾶραι</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λογισμῶν</span> purificar-se dos pensamentos Dg 2:1 ( <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπό</span>, como em Appian , Bell. Civ. 2, 1 §2; Jos. , Ant. 13, 34 ).</p><p class=\"entry-text\">② remover o crescimento supérfluo de uma planta; limpar, podar, referindo-se a uma videira ( cf. Philo , Agr . 10, Somn. 2, 64 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:2</a>. — DELG sob o verbete <span class=\"greek\">καθαρός</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθάπερ</h1><div class=\"entry-meta\"><span>conjunção; advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">conjunção ou advérbio (autores áticos ; inscrições e papiros ; LXX ; TestJud 21:6 [a]; ApcMos 17; EpArist 11 ; Philo ; Jos. , Bell. 4, 406 , C. Ap. 1, 74 ; 130 e frequentemente [BBrüne, Josephus 1912, 34]; Just ., D . 29, 3; Tat ; Mel. , Fgm. 8b, 26) assim como; na literatura aqui considerada, apenas em Paulo, Hebreus e Dg . <span class=\"greek\">κ</span>. <span class=\"greek\">γέγραπται</span> (a formulação confere um tom oficial solene ao texto, cf. <span class=\"greek\">ὅπως</span> <span class=\"greek\">συντελεσθῇ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅρκος</span> <span class=\"greek\">καθάπερ</span> <span class=\"greek\">γέγραπται</span> SIG 1007, 35 [II b.c. ]; semelhantemente <span class=\"greek\">καθάπερ</span> <span class=\"greek\">Ἴωνες</span> <span class=\"greek\">δεδώκασι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῆι</span> <span class=\"greek\">στήλῃ</span> <span class=\"greek\">ἀναγέγραπται</span> IPriene 201, 8f [reconstituído]) como variante de leitura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a> ; 9:13 ; 10:15 ; 11:8 (sempre em lugar de <span class=\"greek\">καθώς</span> ; cf. Philod ., <span class=\"greek\">εὐσεβ</span> . 60 Gomp. <span class=\"greek\">καθάπερ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἠοίαις</span> =como se lê nas Eoiai [obra de Hesíodo perdida, salvo alguns fragmentos]).— <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>, 18 ( variante de leitura <span class=\"greek\">καθώσπερ</span> ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:11</a>. Por assim dizer ( Diod S 14, 1, 4a) Dg 3:3 . <span class=\"greek\">καθάπερ</span> <span class=\"greek\">καί</span> assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:6</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:6</a>, 12 ; 4:5 ; Dg 2:1 ( Just ., D . 29, 3; Tat . 5, 3). Emprega-se frequentemente de modo elíptico, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:2</a>, mas o verbo pode ser facilmente subentendido pelo contexto: <span class=\"greek\">οὐ</span> <span class=\"greek\">κ</span>. … <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀλλά</span> não como … mas Dg 7:2 ; <span class=\"greek\">κ</span>. … <span class=\"greek\">οὕτως</span> assim como … assim também ( Diod S 23, 14, 3; 23, 15, 11; 27, 18, 2; Ps. - Demetr . 186; 2 Macc 2:29 ; 6:14 ; 15:39 ; 4 Macc 15:31f ; Tat . 8, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:4</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12</a> ; sem verbo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a> variante de leitura (em lugar de <span class=\"greek\">καθώσπερ</span>); ver também <span class=\"greek\">καθώς</span> .—FDanker, Gingrich Festschr. , ’72, 99f.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθάπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">κατά</span> e <span class=\"greek\">ἅπτω</span> ) 1º aoristo <span class=\"greek\">καθῆψα</span> (na voz média desde Homero e outros ; na voz ativa em autores trágicos e outros ) agarrar, apoderar-se de (é geralmente a voz média, aqui atestada como variante de leitura, que possui esse significado [ cf. Jos. , Bell. 3, 319 ; 385 ; referindo-se ao sol SSol 1:6 Sym. «queimar»]; Just ., D . 137, 2, <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἠγαπημένου</span> <span class=\"greek\">καθαπτόμενος</span> , mas a voz ativa também o apresenta [ Ps. -Xenophon, Cyneg. 6, 9; Polyb . 8, 8, 3]) <span class=\"greek\">τινός</span> alguma coisa ( citado em Pólux 1, 164; Epict . 3, 20, 10 <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τραχήλου</span> <span class=\"greek\">καθάπτων</span> ) referindo-se a uma serpente <span class=\"greek\">καθῆψεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χειρὸς</span> <span class=\"greek\">αὐτοῦ</span> ela se prendeu à mão dele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:3</a>. — DELG sob o verbete <span class=\"greek\">ἅπτω</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθαρός</span> ; Aristoph ., Pla .+; papiros, Fílon ; TestReub 6:1 , 2 ; Just ., D . 49, 7) estar puro, limpo Ox 840, 23 e 24. <span class=\"greek\">κ</span>. <span class=\"greek\">τινός</span> estar livre de algo ( Pla ., Ep. 8 p. 356e; Plut ., Phoc. 37, 2 <span class=\"greek\">φόνου</span> , Cato Min. 24, 6 <span class=\"greek\">ἁμαρτημάτων</span> ; Ael. Aristid. 44 p. 828 D . <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰσχρῶν</span> ; Herm. Wr. 6, 3 <span class=\"greek\">τ</span>. <span class=\"greek\">κακίας</span> ; CPR I, 232, 34 <span class=\"greek\">πάσης</span> <span class=\"greek\">αἰτίας</span> ; Philo , Rer. Div. Her. 7 <span class=\"greek\">ἁμαρτημάτων</span> ; Jos. , Ant. 1, 102 <span class=\"greek\">φόνου</span> , Vi. 79 ) <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματός</span> <span class=\"greek\">τινος</span> livre do sangue de alguém GPt 11:46.— DELG sob o verbete <span class=\"greek\">καθαρός</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete seguinte; também <span class=\"greek\">καθερίζω</span> ; ver B-D-F § 29, 1 ; W-S. §5, 20c; Mlt-H. 67) futuro ático <span class=\"greek\">καθαριῶ</span> ( <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:2</a> D ; B-D-F § 101 sob o verbete <span class=\"greek\">καθαίρειν</span> ; ver Mlt-H. 218); 3ª pessoa do singular - <span class=\"greek\">ίσει</span> ( Num 30:13 códice B ; Mal 3:3) 1º aoristo <span class=\"greek\">ἐκαθάρισα</span> , imperativo <span class=\"greek\">καθάρισον</span> . Passivo: futuro <span class=\"greek\">καθαρισθήσομαι</span> LXX; 1º aoristo <span class=\"greek\">ἐκαθαρίσθην</span> (também <span class=\"greek\">ἐκαθερίσθην</span> : <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:3b</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:42</a> variante de leitura ), imperativo <span class=\"greek\">καθαρίσθητι</span> ; perfeito, 3ª pessoa do singular <span class=\"greek\">κεκαθάρισται</span> ( 1 Km 20:26 ; TestJob 43:17), particípio <span class=\"greek\">κεκαθαρισμένος</span> . Ver Reinhold 38f; Thackeray 74. (Substituto do termo-padrão <span class=\"greek\">καθαίρω</span> no grego helenístico : como termo técnico agrícola PLond I 131 recto, 192 p. 175 [78/79 a.d. ]; PStras 2, 11; PLips 111, 12. No sentido ritual, inscrição dos mistérios de Andânia= SIG 736, 37; semelhantemente 1042, 3; Jos. , Ant. 10, 70 ; 11, 153 ; 12 , 286 ; Just ., Mel. , P. 72, 526. O vocábulo é também atestado BGU 1024 IV, 16; EpArist 90 e em diversos significados na LXX ; En 10:20 , 22 ; TestJob ; TestReub 4:8 ; TestLevi 14:6 .— Dssm. , NB 43f [ BS 216f]; em vários sentidos: «limpar, desobstruir [como uma área], purificar»)</p><p class=\"entry-text\">① tornar fisicamente limpo; limpar, higienizar <span class=\"greek\">τί</span>, alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:25f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:39</a>. A passagem muito debatida <span class=\"greek\">καθαρίζων</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">βρώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:19</a> talvez pertença a esta acepção (assim interpretam BWeiss; HHoltzmann; Schniewind), mas ver a acepção 3a abaixo.</p><p class=\"entry-text\">② curar uma pessoa de doença que a torna cerimonialmente impura; limpar, curar, sobretudo a lepra</p><p class=\"entry-text\">ⓐ <span class=\"greek\">τινά</span>, tornar alguém limpo; purificar alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:2</a> ; 10:8 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:40</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12</a> ; AcPl Ha 8, 36//BMM verso 10; ver também BMM verso 12 e 39 ( Mel. , P. 72, 526 <span class=\"greek\">τοὺς</span> <span class=\"greek\">λεπρούς</span> ). Passivo ( Lev 14:7 al. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:5</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:42</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:27</a> ; 7:22 ; 17:14, 17 ; PEg 2 37; <span class=\"greek\">καθαρίσθητι</span> (cf. 4 Km 5:13 ) fica limpo! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:3a</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:41</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:13</a> ; 17:14 variante de leitura ; PEg 2 38.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">τί</span>, remover algo por meio da purificação ou com a finalidade de purificar ( cf. Od . 6, 93 <span class=\"greek\">καθαίρειν</span> <span class=\"greek\">ῥύπα</span> ; Epict . 2, 16, 44; 3, 24, 13) pass. <span class=\"greek\">ἐκαθαρίσθη</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">λέπρα</span> sua lepra desapareceu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:3b</a>.</p><p class=\"entry-text\">③ purificar mediante limpeza ritual; tornar limpo, declarar limpo</p><p class=\"entry-text\">ⓐ purificação levítica dos alimentos: tornar limpo, declarar limpo ( cf. Lev 13:6, 23 ) <span class=\"greek\">ἃ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐκαθάρισεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:15</a> ; 11:9. Muitos (Orígenes; Field, Notes 31f; entre outros) preferem entender <span class=\"greek\">καθαρίζων</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βρώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:19</a> (ver a acepção 1 acima) nesse sentido, tomando as palavras como observação do evangelista ou anotação marginal de um leitor: ele (Jesus), com isso, declara limpos todos os alimentos —WBrandt, Jüd. Reinheitslehre u. ihre Beschreibung in den Evang. 1910.</p><p class=\"entry-text\">ⓑ referindo-se à purificação moral e cultual <span class=\"greek\">α</span>. limpar, purificar do pecado ( LXX ) <span class=\"greek\">τινά</span> ou <span class=\"greek\">τί</span>: ( <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span> Hippol ., Ref. 10, 14, 10) <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> Hs 6, 5, 2 . <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> v 3, 9, 8 . <span class=\"greek\">χεῖρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:8</a> ; <span class=\"greek\">ἑαυτούς</span> Hs 8, 7, 5 ; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐντὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ποτηρίου</span> o conteúdo do copo, que não deve ser adquirido de maneira pecaminosa nem utilizado para finalidade pecaminosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:26</a>. <span class=\"greek\">ἐλθέτω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγ</span>. <span class=\"greek\">πνεῦμά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καθαρισάτω</span> <span class=\"greek\">ἡμᾶς</span> venha o teu Espírito Santo sobre nós e purifique-nos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a> variante de leitura Em parábola <span class=\"greek\">τοὺς</span> <span class=\"greek\">λίθους</span> Hs 9, 7, 2 e 6 ; 9, 8, 4 .—Passivo Hv 4, 3, 4 . <span class=\"greek\">ἅπαξ</span> <span class=\"greek\">κεκαθαρισμένους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:2</a>. <span class=\"greek\">καθαρισθήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> Hs 9, 18, 2 ; cf. 3 . <span class=\"greek\">καθαρισθήσομαι</span> 1 Cl 18:7 ( Ps 50:9 ).— <span class=\"greek\">τινὰ</span> (<span class=\"greek\">τὶ</span>) <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (sobre a construção com <span class=\"greek\">ἀπό</span>, ver as duas passagens de SIG no começo daquele verbete; Lev 16:30 <span class=\"greek\">καθαρίσαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτιῶν</span> ; Ps 18:14 ; 50:4 ; Sir 23:10 ; 38:10 e frequentemente ; En 10:20 , 22 ; PsSol 10:1 ; 17:22 ; Jos. , Ant. 12, 286 ; TestReub 4:8 ; Just ., D . 116, 2) <span class=\"greek\">κ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἁμαρτίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 J 1:7</a> ; cf. o versículo 9 ; 1 Cl 18:3 ( Ps 50:4 ). <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μολυσμοῦ</span> <span class=\"greek\">σαρκός</span> purificar-se da contaminação da carne <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span> Hm 10, 3, 4 . <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἐπιθυμίας</span> Hs 7:2 . <span class=\"greek\">τῶν</span> <span class=\"greek\">πονηριῶν</span> 8, 11, 3 ; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαιμονίου</span> 9, 23, 5 . <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διψυχίας</span> purificar o coração da dúvida m 9:7 . <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ματαιωμάτων</span> das vaidades 9:4. <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπιθυμιῶν</span> 12, 6, 5. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἔργων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:14</a>. Passivo <span class=\"greek\">καθαρίζεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτιῶν</span> Hv 2, 3, 1 ; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑστερημάτων</span> 3, 2, 2a ; cf. b e 3, 8, 11 .— <span class=\"greek\">κ</span>. <span class=\"greek\">τινά</span> (<span class=\"greek\">τί</span>) <span class=\"greek\">τινι</span> ( dativo instrumental ): <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">καθαρίσας</span> ( isto é, Deus) <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:9</a>. Referindo-se a Cristo e à comunidade cristã <span class=\"greek\">καθαρίσας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λουτρῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥήματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:26</a> (OCasel, Jahrb. für Liturgiewiss. 5, 1925, 144ff). Referindo-se a Cristo e ao batismo <span class=\"greek\">ἵνα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πάθει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">καθαρίσῃ</span> para que, por meio de seu sofrimento, ele purificasse a água IEph 18:2 .— <span class=\"greek\">καθάρισον</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καθαρισμὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σῆς</span> <span class=\"greek\">ἀληθείας</span> purifica-nos com a purificação de tua verdade 1 Cl 60:2 .—Referindo-se a Cristo e aos cristãos <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">περιούσιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:14</a>. —PEg 3 57f. <span class=\"greek\">β</span>. remover por meio de purificação ou com o objetivo de purificar <span class=\"greek\">τὶ</span>, alguma coisa (ver a acepção 2b e cf. Dt 19:13 ; <span class=\"greek\">κεκαθάρισται</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνομία</span> TestJob 43:17) <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">τινός</span> Hs 5, 6, 2f .</p><p class=\"entry-text\">ⓒ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:22f</a> ocupa uma posição intermediária, pois a purificação cerimonial e a moral se fundem, e a primeira passa a ser imagem ou sombra da segunda.</p><p class=\"entry-text\">ⓓ libertar <span class=\"greek\">τινά</span> <span class=\"greek\">τινος</span>, alguém de alguma coisa 1 Cl 16:10 ( Is 53:10 ).— DELG sob o verbete <span class=\"greek\">καθαρός</span> . M-M . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( de <span class=\"greek\">καθαρίζω</span> ; ocorre como termo técnico agrícola [ver o início do verbete <span class=\"greek\">καθαρίζω</span> ] PMich 185, 16 [122 a.d. ]; PLond II, 168, 11 p. 190 [162 a.d. ]; no sentido de «propiciação» em Ps.-Lucian , Asin. 22; atestado também em LXX ; TestLevi 14:6 e em Achmes 92, 19 variante de leitura Substitui o muito mais frequente <span class=\"greek\">καθαρμός</span> )</p><p class=\"entry-text\">① eliminação da impureza cultual; purificação ( 2 Macc 2:16 referindo-se à dedicação de um templo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:25</a>. Com genitivo subjetivo <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> 2:6. Com genitivo objetivo de pessoa : <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a> ( Manetão em Jos. , C. Ap. 1, 282 trata das cerimônias às quais se submete uma pessoa curada da lepra). <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καθαρισμοῦ</span> <span class=\"greek\">αὐτῶν</span> (cf. Ex 29:36 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:22</a> inclui José na purificação, embora apenas a mulher fosse obrigada a submeter-se à purificação ( Aristot ., HA 7, 10 p, 587b, 1ff isso é denominado <span class=\"greek\">καθαρμός</span> ); o pronome <span class=\"greek\">αὐτῶν</span> talvez seja um uso coloquial que explica a presença de José no procedimento.</p><p class=\"entry-text\">② purificação de contaminação interior; purificar, extensão figurada da acepção 1 ( TestLevi 14:6 variante de leitura ) 1 Cl 60:2 (ver <span class=\"greek\">καθαρίζω</span> 3b <span class=\"greek\">α</span> ). <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ποιεῖσθαι</span> produzir purificação dos pecados (cf. Job 7:21 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>. — DELG sob o verbete <span class=\"greek\">καθαρός</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθαρμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( trágicos e outros ; referindo-se a pessoas: Aristoph ., Plutus 454; Demosth . 21, 185; Dio Chrys . 13 [7], 30; Diog. L. 6, 32 <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ἐκάλεσα</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">καθάρματα</span> ; Philostrat ., Vi. Apoll. 1, 12; Synes ., Ep. 148 p. 288a [referindo-se aos Ciclopes]; Philo , Virt. 174; Jos. , Bell. 4, 241 ) refugo, em lugar de <span class=\"greek\">περικάθαρμα</span> ( ver verbete ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:13</a> variante de leitura — DELG sob o verbete <span class=\"greek\">καθαρός</span> . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθαρίζω</span> ; Homero e posteriores)</p><p class=\"entry-text\">① relativo ao estado de limpeza ou à ausência de substâncias adulterantes: limpo, puro, referindo-se a um copo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:26</a>. <span class=\"greek\">σινδών</span> linho limpo ( PGM 4, 1861; 2189; 3095; 5, 217) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:59</a>. <span class=\"greek\">λίνον</span> <span class=\"greek\">καθαρὸν</span> <span class=\"greek\">λαμπρόν</span> (variante de leitura <span class=\"greek\">λίθον</span> ; sobre isso, ver Fílon , Mos. 2, 72 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a>. <span class=\"greek\">βύσσινον</span> <span class=\"greek\">λαμπρὸν</span> <span class=\"greek\">κ</span> . 19:8 ; cf. versículo 14 ; <span class=\"greek\">ὠμόλινον</span> <span class=\"greek\">κ</span> . Hs 8, 4, 1 . <span class=\"greek\">ὕδωρ</span> água pura, limpa ( Eur ., Hipp. 209; SIG 972, 169; PGM 4, 3252; Ezk 36:25 ; Philo , Spec. Leg. 3, 58 ; Mel. , Fgm. 8b, 17; 40 P.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a>. Referindo-se a metais ( Hdt. 4, 166; Aristot ., Meteor. 383b, 1; Theocr . 15, 36 <span class=\"greek\">ἀργύριον</span> ; Plut ., Alex. 684 [32, 9] <span class=\"greek\">ἄργυρος</span> ; Sb 4481, 13 <span class=\"greek\">σίδηρος</span> ) <span class=\"greek\">χρυσίον</span> <span class=\"greek\">κ</span> . ouro puro ( Diod S 3, 14, 4; Ex 25:31 ; 2 Ch 3:5 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:18a</a>, 21 ; <span class=\"greek\">ὕαλος</span> <span class=\"greek\">κ</span> . cristal transparente versículo 18b. Na linguagem figurada de Inácio, em referência ao martírio, aparece o conceito <span class=\"greek\">κ</span>. <span class=\"greek\">ἄρτος</span> ( Hdt. 2, 40; Teles p. 40, 11; Dio Chrys . 13 [7], 76 al. ; Jur. Pap. 36, 29; POxy 736, 26) pão (de trigo) puro, sem mistura IRo 4:1 . <span class=\"greek\">κ</span>. <span class=\"greek\">φῶς</span> luz pura IRo 6:2 .— <span class=\"greek\">ὁ</span> <span class=\"greek\">λελουμένος</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">ὅλος</span> a pessoa que se banhou está inteiramente limpa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10a</a>.</p><p class=\"entry-text\">② relativo à pureza cultual ou cerimonial: ritualmente puro (inscrições; PGM 4, 3084; 3085; LXX ; Iren. 3, 12, 7 [ Harv. II 60, 3]; Did. , Gen. 177, 13) referindo-se ao templo <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> … <span class=\"greek\">καθαρόν</span> Ox 840, 17f. <span class=\"greek\">πάντα</span> <span class=\"greek\">καθαρά</span> tudo é ritualmente puro e, portanto, apropriado para uso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:15ac</a>.</p><p class=\"entry-text\">③ relativo à ausência de culpa moral: puro, livre de pecado ( Pind ., P. 5, 2; Pla ., Rep. 6 p. 496d <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">ἀδικίας</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνοσίων</span> <span class=\"greek\">ἔργων</span> , Crat. 403e; 405b al. ; LXX ; PsSol 17:36 ; EpArist , Philo , Joseph .; TestBenj 8:2 f; <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ψυχήν</span> Theoph. Ant. 1, 2 [p. 60, 22]).</p><p class=\"entry-text\">ⓐ referindo-se à pessoa em si <span class=\"greek\">οἱ</span> <span class=\"greek\">καθαροί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:15b</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10b</a>, 11 ; 15:3. Os cristãos são o <span class=\"greek\">λαὸς</span> <span class=\"greek\">κ</span> . («povo puro») de Cristo Hs 9, 18, 4 . <span class=\"greek\">οἱ</span> <span class=\"greek\">καθαροὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> ( Ps 23:4 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:8</a> ; cf. PEg 3 45 ( <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> reconstituído), 47f ( <span class=\"greek\">καρδίας</span> reconstituído). <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">συνειδήσει</span> ITr 7:2b ; sem culpa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:6</a>. <span class=\"greek\">καθαρά</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γινώσκω</span> sou inocente e continuo virgem GJs 13:3. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> livre de ( Ps. - Demosth . 59, 78; Cass. Dio 37, 24, 2. Exemplos de papiros e inscrições em Dssm. , NB 24 [ BS 196]; PGM 13, 648; 1004; Gen 24:8 ; Pr 20:9 ; Tob 3:14 ; PsSol 17:36 ; Jos. , Ant. 4, 222 ; Ath. 12, 3; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἁμαρτίας</span> Orig ., C. Cels. 7, 50, 6) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἵματος</span> ( Sus 46 Theod. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:26</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ῥύπου</span> 1 Cl 17:4 ( Job 14:4 ). <span class=\"greek\">καθαρός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῆς</span> não tenho culpa no que diz respeito a ela GJs 15:4. Diante de Deus <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">αὐτοῦ</span> 15:3.—Também aplicado ao Espírito Santo Hm 5, 1, 2 , imagem figurativa de luminosidade.</p><p class=\"entry-text\">ⓑ referindo-se às coisas vinculadas à pessoa como ser moral ou espiritualmente responsável <span class=\"greek\">κ</span>. <span class=\"greek\">καρδία</span> ( Lucian , Nigr. 14 <span class=\"greek\">κ</span>. <span class=\"greek\">ἦθος</span> ; Simplicius in Epict . p. 93, 49 <span class=\"greek\">ζωὴ</span> <span class=\"greek\">κ</span> .; Gen 20:5 ; Ps 50:12 ; cf. <span class=\"greek\">κ</span>. <span class=\"greek\">ψυχή</span> : Pythagoras in Diog. L. 8, 31; Diod S 12, 20, 2; 13, 29, 6; <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κ</span> . Ath. 27:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:5</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:22</a> ; B 15:1 ; 1 Cl 18:10 ; Hv 3, 9, 8 ; <span class=\"greek\">σάρξ</span> Hs 5, 7, 1 ; <span class=\"greek\">κ</span>. <span class=\"greek\">συνείδησις</span> ( POslo 17, 10 [136 a.d. ]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:3</a> ; 1 Cl 45:7 ( cf. <span class=\"greek\">κ</span>. <span class=\"greek\">συνειδός</span> : Philo , Spec. Leg. 1, 203 , Praem. 84); <span class=\"greek\">θρησκεία</span> <span class=\"greek\">κ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>. <span class=\"greek\">χεῖρες</span> <span class=\"greek\">καθαραί</span> ( Aeschyl ., Eum. 313, também Plut ., Pericl. 8, 8; SIG 983, 5; Job 9:30 ; 22:30 ; Philo , Virt. 57; Jos. , Bell. 5, 380 , Ant. 4, 222 ; Just ., D . 12, 3) B 15:1 . <span class=\"greek\">μετάνοια</span> <span class=\"greek\">κ</span> . Hm 2:7 ; 12, 3, 2 . <span class=\"greek\">διάνοια</span> 1 Cl 1:8 ; Hs 4:7 . <span class=\"greek\">αφ</span>.11.6.14 . m 5, 1, 3 . <span class=\"greek\">ἔντευξιν</span> 10, 3, 3 .</p><p class=\"entry-text\">④ relativo à pureza ritual e moral: puro; fundem-se a pureza ritual e a moral ( Simplicius in Epict . p. 111, 18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:41</a>. Após uma confissão de pecados <span class=\"greek\">καθαρὰ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θυσία</span> <span class=\"greek\">ὑμῶν</span> D 14:1 , 3 . <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐντὸς</span> <span class=\"greek\">θυσιαστηρίου</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">καθαρός</span> <span class=\"greek\">ἐστιν</span> ITr 7:2a .—TWächter, Reinheitsvorschriften im griech. Kult 1910; FPfister, Katharsis.— M-M . Pauly-W . Suppl. IV ’35, 146ff.— DELG . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0180-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθαρός</span> ; X. , Mem. 2, 1, 22 al. ; Cecílio, o orador [I b.c. ] p. 98, 7; 107, 1 EOfenloch [1907] referindo-se à pureza da linguagem; Epict . 4, 11, 5; POxy 67, 6; 904, 2; Ex 24:10 variante de leitura ; Wsd 7:24 ; EpArist 234 ; TestNapht 3:1 ; <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοῦ</span> <span class=\"greek\">κ</span> . Did. , Gen. 114, 10; Orig ., C. Cels. 1, 26, 51 como qualidade das pessoas piedosas) estado ou condição de ter sido ritualmente purificado; pureza: <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:13</a> (s. also Iambl ., Vita Pyth. 24, 106 <span class=\"greek\">καθαρότης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> ; Did. , Gen. 151, 11). <span class=\"greek\">ἐν</span> <span class=\"greek\">καθαρότη</span>[<span class=\"greek\">τι</span> <span class=\"greek\">καταστήσει</span>] [proporcionará hospedagem] em pureza (=‘praticará a pureza enquanto proporcionar hospedagem [às jovens]’) Hs 10, 3, 4 ( POxy 404 recto, 118f).— DELG sob o verbete <span class=\"greek\">καθαρός</span> . M-M . TW .</p></section></article>\n"};
